import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useQuery, useMutation } from '@apollo/client';
import { 
  Box, Grid, Paper, Typography, Button, IconButton, Tooltip, 
  Tabs, Tab, FormControl, InputLabel, Select, MenuItem, 
  Table, TableBody, TableCell, TableContainer, TableHead, 
  TableRow, Checkbox, TablePagination, TextField, InputAdornment,
  Snackbar, Alert, Dialog, DialogTitle, DialogContent, DialogActions,
  useTheme, useMediaQuery, Badge, Chip, Divider, Card, CardContent
} from '@mui/material';
import { 
  Add as AddIcon, 
  Edit as EditIcon, 
  Delete as DeleteIcon,
  Refresh as RefreshIcon,
  Search as SearchIcon,
  FilterList as FilterListIcon,
  ViewColumn as ViewColumnIcon,
  BarChart as BarChartIcon,
  PieChart as PieChartIcon,
  TableChart as TableChartIcon,
  Settings as SettingsIcon,
  Keyboard as KeyboardIcon,
  Close as CloseIcon,
  Check as CheckIcon,
  Clear as ClearIcon,
  EventNote as EventNoteIcon,
  Email as EmailIcon,
  Phone as PhoneIcon,
  Person as PersonIcon,
  CalendarToday as CalendarIcon,
  AccessTime as TimeIcon,
  CheckCircle as CheckCircleIcon,
  PendingActions as PendingActionsIcon,
  Cancel as CancelIcon,
  DoneAll as DoneAllIcon
} from '@mui/icons-material';
import { format, subDays, startOfDay, endOfDay, isSameDay } from 'date-fns';
import { useHotkeys } from 'react-hotkeys-hook';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { 
  GET_ALL_APPOINTMENTS, 
  GET_ALL_CONTACTS,
  UPDATE_APPOINTMENT_STATUS,
  DELETE_APPOINTMENT,
  UPDATE_CONTACT_STATUS
} from '../../graphql/admin';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';

// Custom Components
const StatCard = ({ title, value, icon: Icon, color = 'primary', trend = 0 }) => (
  <Card sx={{ height: '100%' }}>
    <CardContent>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={1}>
        <Typography color="textSecondary" variant="subtitle2">{title}</Typography>
        <Icon color={color} />
      </Box>
      <Typography variant="h4">{value}</Typography>
      {trend !== 0 && (
        <Box display="flex" alignItems="center" mt={1}>
          {trend > 0 ? (
            <CheckCircleIcon color="success" fontSize="small" />
          ) : (
            <CancelIcon color="error" fontSize="small" />
          )}
          <Typography 
            variant="caption" 
            color={trend > 0 ? 'success.main' : 'error.main'}
            sx={{ ml: 0.5 }}
          >
            {Math.abs(trend)}% from last month
          </Typography>
        </Box>
      )}
    </CardContent>
  </Card>
);

const StatusChip = ({ status }) => {
  const statusConfig = {
    PENDING: { label: 'Pending', color: 'warning' },
    CONFIRMED: { label: 'Confirmed', color: 'info' },
    COMPLETED: { label: 'Completed', color: 'success' },
    CANCELLED: { label: 'Cancelled', color: 'error' },
    UNREAD: { label: 'Unread', color: 'default' },
    READ: { label: 'Read', color: 'primary' },
    RESPONDED: { label: 'Responded', color: 'success' }
  };

  const config = statusConfig[status] || { label: status, color: 'default' };

  return (
    <Chip 
      label={config.label}
      color={config.color}
      size="small"
      variant="outlined"
    />
  );
};

// Main Component
const EnhancedDashboard = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const navigate = useNavigate();
  const { logout } = useAuth();

  // State
  const [activeTab, setActiveTab] = useState(0);
  const [selected, setSelected] = useState([]);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [searchText, setSearchText] = useState('');
  const [filters, setFilters] = useState({
    status: '',
    dateRange: {
      start: subDays(new Date(), 30),
      end: new Date()
    }
  });
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'info'
  });
  const [viewMode, setViewMode] = useState('table'); // 'table' or 'chart'
  const [showFilters, setShowFilters] = useState(false);
  const [showShortcuts, setShowShortcuts] = useState(false);
  const [showColumnSelector, setShowColumnSelector] = useState(false);

  // Columns visibility
  const [visibleColumns, setVisibleColumns] = useState({
    name: true,
    email: true,
    phone: true,
    service: true,
    date: true,
    status: true,
    actions: true
  });

  // Fetch data
  const { data: appointmentsData, loading: loadingAppointments, refetch: refetchAppointments } = useQuery(GET_ALL_APPOINTMENTS, {
    fetchPolicy: 'network-only'
  });

  const { data: contactsData, loading: loadingContacts, refetch: refetchContacts } = useQuery(GET_ALL_CONTACTS, {
    fetchPolicy: 'network-only'
  });

  // Mutations
  const [updateAppointmentStatus] = useMutation(UPDATE_APPOINTMENT_STATUS);
  const [deleteAppointment] = useMutation(DELETE_APPOINTMENT);
  const [updateContactStatus] = useMutation(UPDATE_CONTACT_STATUS);

  // Processed data
  const appointments = useMemo(() => {
    return appointmentsData?.allAppointments || [];
  }, [appointmentsData]);

  const contacts = useMemo(() => {
    return contactsData?.allContacts || [];
  }, [contactsData]);

  // Filtered data
  const filteredData = useMemo(() => {
    const data = activeTab === 0 ? appointments : contacts;
    return data.filter(item => {
      // Search filter
      const matchesSearch = Object.values(item).some(value => 
        String(value).toLowerCase().includes(searchText.toLowerCase())
      );

      // Status filter
      const matchesStatus = !filters.status || item.status === filters.status;

      // Date range filter
      let matchesDate = true;
      if (item.createdAt || item.appointmentDate) {
        const date = new Date(item.createdAt || item.appointmentDate);
        matchesDate = date >= startOfDay(new Date(filters.dateRange.start)) && 
                     date <= endOfDay(new Date(filters.dateRange.end));
      }

      return matchesSearch && matchesStatus && matchesDate;
    });
  }, [activeTab, appointments, contacts, searchText, filters]);

  // Pagination
  const paginatedData = useMemo(() => {
    return filteredData.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage);
  }, [filteredData, page, rowsPerPage]);

  // Handlers
  const handleSelectAll = (event) => {
    if (event.target.checked) {
      const newSelecteds = paginatedData.map((n) => n.id);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const handleSelect = (id) => {
    const selectedIndex = selected.indexOf(id);
    let newSelected = [];

    if (selectedIndex === -1) {
      newSelected = newSelected.concat(selected, id);
    } else if (selectedIndex === 0) {
      newSelected = newSelected.concat(selected.slice(1));
    } else if (selectedIndex === selected.length - 1) {
      newSelected = newSelected.concat(selected.slice(0, -1));
    } else if (selectedIndex > 0) {
      newSelected = newSelected.concat(
        selected.slice(0, selectedIndex),
        selected.slice(selectedIndex + 1),
      );
    }

    setSelected(newSelected);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleStatusChange = async (id, newStatus, type) => {
    try {
      if (type === 'appointment') {
        await updateAppointmentStatus({
          variables: {
            appointmentId: id,
            status: newStatus
          },
          refetchQueries: [{ query: GET_ALL_APPOINTMENTS }]
        });
      } else {
        await updateContactStatus({
          variables: {
            contactId: id,
            status: newStatus
          },
          refetchQueries: [{ query: GET_ALL_CONTACTS }]
        });
      }
      showSnackbar('Status updated successfully', 'success');
    } catch (error) {
      console.error('Error updating status:', error);
      showSnackbar('Failed to update status', 'error');
    }
  };

  const handleBulkStatusUpdate = async (status) => {
    try {
      const updates = selected.map(id => {
        return activeTab === 0 
          ? updateAppointmentStatus({
              variables: { appointmentId: id, status },
              refetchQueries: [{ query: GET_ALL_APPOINTMENTS }]
            })
          : updateContactStatus({
              variables: { contactId: id, status },
              refetchQueries: [{ query: GET_ALL_CONTACTS }]
            });
      });

      await Promise.all(updates);
      setSelected([]);
      showSnackbar(`Updated status for ${selected.length} items`, 'success');
    } catch (error) {
      console.error('Bulk update error:', error);
      showSnackbar('Failed to update selected items', 'error');
    }
  };

  const handleBulkDelete = async () => {
    if (!window.confirm(`Are you sure you want to delete ${selected.length} selected items?`)) return;

    try {
      const deletions = selected.map(id => {
        return activeTab === 0
          ? deleteAppointment({
              variables: { input: { id } },
              refetchQueries: [{ query: GET_ALL_APPOINTMENTS }]
            })
          : Promise.resolve(); // Add contact deletion mutation if available
      });

      await Promise.all(deletions);
      setSelected([]);
      showSnackbar(`Deleted ${selected.length} items`, 'success');
    } catch (error) {
      console.error('Bulk delete error:', error);
      showSnackbar('Failed to delete selected items', 'error');
    }
  };

  const handleRefresh = () => {
    if (activeTab === 0) {
      refetchAppointments();
    } else {
      refetchContacts();
    }
    showSnackbar('Data refreshed', 'info');
  };

  const showSnackbar = (message, severity = 'info') => {
    setSnackbar({
      open: true,
      message,
      severity
    });
  };

  const closeSnackbar = () => {
    setSnackbar(prev => ({ ...prev, open: false }));
  };

  // Keyboard Shortcuts
  useHotkeys('r', (e) => {
    e.preventDefault();
    handleRefresh();
  });

  useHotkeys('f', (e) => {
    e.preventDefault();
    setShowFilters(!showFilters);
  });

  useHotkeys('k', (e) => {
    e.preventDefault();
    setShowShortcuts(!showShortcuts);
  });

  useHotkeys('esc', () => {
    setShowFilters(false);
    setShowShortcuts(false);
    setShowColumnSelector(false);
  });

  // Stats
  const stats = useMemo(() => {
    const today = new Date();
    const thisWeekStart = startOfDay(subDays(today, today.getDay()));
    const thisMonthStart = startOfDay(new Date(today.getFullYear(), today.getMonth(), 1));

    const recentAppointments = appointments.filter(appt => 
      new Date(appt.appointmentDate) >= thisWeekStart
    );

    const pendingAppointments = appointments.filter(
      appt => appt.status === 'PENDING'
    ).length;

    const newMessages = contacts.filter(
      contact => contact.status === 'UNREAD' || contact.status === 'READ'
    ).length;

    const completedThisMonth = appointments.filter(
      appt => appt.status === 'COMPLETED' && 
      new Date(appt.appointmentDate) >= thisMonthStart
    ).length;

    return {
      totalAppointments: appointments.length,
      pendingAppointments,
      newMessages,
      completedThisMonth,
      recentAppointments
    };
  }, [appointments, contacts]);

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box sx={{ mb: 4 }}>
        <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
          <Typography variant="h4" component="h1">
            Dashboard Overview
          </Typography>
          <Box>
            <Tooltip title="Keyboard Shortcuts (K)">
              <IconButton onClick={() => setShowShortcuts(true)}>
                <KeyboardIcon />
              </IconButton>
            </Tooltip>
            <Button 
              variant="contained" 
              color="primary" 
              startIcon={<RefreshIcon />}
              onClick={handleRefresh}
              sx={{ ml: 1 }}
            >
              Refresh
            </Button>
          </Box>
        </Box>

        {/* Stats Cards */}
        <Grid container spacing={3} sx={{ mb: 3 }}>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard 
              title="Total Appointments" 
              value={stats.totalAppointments}
              icon={EventNoteIcon}
              color="primary"
              trend={5.5}
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard 
              title="Pending" 
              value={stats.pendingAppointments}
              icon={PendingActionsIcon}
              color="warning"
              trend={-2.3}
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard 
              title="New Messages" 
              value={stats.newMessages}
              icon={EmailIcon}
              color="info"
              trend={12.1}
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard 
              title="Completed This Month" 
              value={stats.completedThisMonth}
              icon={CheckCircleIcon}
              color="success"
              trend={8.7}
            />
          </Grid>
        </Grid>
      </Box>

      {/* Main Content */}
      <Paper sx={{ p: 2, mb: 3 }}>
        {/* Toolbar */}
        <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
          <Tabs 
            value={activeTab} 
            onChange={(e, newValue) => {
              setActiveTab(newValue);
              setPage(0);
              setSelected([]);
            }}
            sx={{ minHeight: 'auto' }}
          >
            <Tab 
              label={
                <Box display="flex" alignItems="center">
                  <EventNoteIcon fontSize="small" sx={{ mr: 1 }} />
                  <span>Appointments</span>
                  <Chip 
                    label={appointments.length} 
                    size="small" 
                    sx={{ ml: 1, height: 20 }}
                  />
                </Box>
              } 
            />
            <Tab 
              label={
                <Box display="flex" alignItems="center">
                  <EmailIcon fontSize="small" sx={{ mr: 1 }} />
                  <span>Messages</span>
                  <Chip 
                    label={contacts.length} 
                    size="small" 
                    sx={{ ml: 1, height: 20 }}
                  />
                </Box>
              } 
            />
          </Tabs>

          <Box>
            <Tooltip title="View Mode">
              <IconButton 
                onClick={() => setViewMode(prev => prev === 'table' ? 'chart' : 'table')}
                color={viewMode === 'chart' ? 'primary' : 'default'}
              >
                {viewMode === 'table' ? <BarChartIcon /> : <TableChartIcon />}
              </IconButton>
            </Tooltip>
            <Tooltip title="Filter">
              <IconButton 
                onClick={() => setShowFilters(!showFilters)}
                color={showFilters ? 'primary' : 'default'}
              >
                <FilterListIcon />
              </IconButton>
            </Tooltip>
            <Tooltip title="Columns">
              <IconButton 
                onClick={() => setShowColumnSelector(!showColumnSelector)}
                color={showColumnSelector ? 'primary' : 'default'}
              >
                <ViewColumnIcon />
              </IconButton>
            </Tooltip>
          </Box>
        </Box>

        {/* Filters */}
        {showFilters && (
          <Box sx={{ p: 2, mb: 3, bgcolor: 'background.default', borderRadius: 1 }}>
            <Grid container spacing={2} alignItems="center">
              <Grid item xs={12} sm={6} md={3}>
                <TextField
                  fullWidth
                  variant="outlined"
                  size="small"
                  placeholder="Search..."
                  value={searchText}
                  onChange={(e) => setSearchText(e.target.value)}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <SearchIcon />
                      </InputAdornment>
                    ),
                  }}
                />
              </Grid>
              <Grid item xs={12} sm={6} md={3}>
                <FormControl fullWidth size="small">
                  <InputLabel>Status</InputLabel>
                  <Select
                    value={filters.status}
                    onChange={(e) => setFilters({...filters, status: e.target.value})}
                    label="Status"
                  >
                    <MenuItem value="">All Statuses</MenuItem>
                    {activeTab === 0 ? (
                      <>
                        <MenuItem value="PENDING">Pending</MenuItem>
                        <MenuItem value="CONFIRMED">Confirmed</MenuItem>
                        <MenuItem value="COMPLETED">Completed</MenuItem>
                        <MenuItem value="CANCELLED">Cancelled</MenuItem>
                      </>
                    ) : (
                      <>
                        <MenuItem value="UNREAD">Unread</MenuItem>
                        <MenuItem value="READ">Read</MenuItem>
                        <MenuItem value="RESPONDED">Responded</MenuItem>
                      </>
                    )}
                  </Select>
                </FormControl>
              </Grid>
              <Grid item xs={12} sm={6} md={4}>
                <LocalizationProvider dateAdapter={AdapterDateFns}>
                  <Box display="flex" gap={2}>
                    <DatePicker
                      label="Start Date"
                      value={filters.dateRange.start}
                      onChange={(date) => 
                        setFilters({...filters, dateRange: {...filters.dateRange, start: date}})
                      }
                      renderInput={(params) => (
                        <TextField {...params} size="small" fullWidth />
                      )}
                    />
                    <DatePicker
                      label="End Date"
                      value={filters.dateRange.end}
                      onChange={(date) => 
                        setFilters({...filters, dateRange: {...filters.dateRange, end: date}})
                      }
                      renderInput={(params) => (
                        <TextField {...params} size="small" fullWidth />
                      )}
                    />
                  </Box>
                </LocalizationProvider>
              </Grid>
              <Grid item xs={12} sm={6} md={2}>
                <Button 
                  fullWidth 
                  variant="outlined" 
                  onClick={() => {
                    setFilters({
                      status: '',
                      dateRange: {
                        start: subDays(new Date(), 30),
                        end: new Date()
                      }
                    });
                    setSearchText('');
                  }}
                >
                  Clear Filters
                </Button>
              </Grid>
            </Grid>
          </Box>
        )}

        {/* Bulk Actions */}
        {selected.length > 0 && (
          <Box sx={{ mb: 2, p: 1, bgcolor: 'action.selected', borderRadius: 1 }}>
            <Box display="flex" alignItems="center">
              <Typography variant="subtitle2" sx={{ mr: 2 }}>
                {selected.length} selected
              </Typography>

              {activeTab === 0 ? (
                <>
                  <FormControl size="small" sx={{ minWidth: 180, mr: 1 }}>
                    <InputLabel>Update Status</InputLabel>
                    <Select
                      value=""
                      onChange={(e) => handleBulkStatusUpdate(e.target.value)}
                      label="Update Status"
                      displayEmpty
                    >
                      <MenuItem value="" disabled>Update Status</MenuItem>
                      <MenuItem value="PENDING">Mark as Pending</MenuItem>
                      <MenuItem value="CONFIRMED">Mark as Confirmed</MenuItem>
                      <MenuItem value="COMPLETED">Mark as Completed</MenuItem>
                      <MenuItem value="CANCELLED">Mark as Cancelled</MenuItem>
                    </Select>
                  </FormControl>
                  <Button
                    variant="outlined"
                    color="error"
                    size="small"
                    startIcon={<DeleteIcon />}
                    onClick={handleBulkDelete}
                    sx={{ mr: 1 }}
                  >
                    Delete
                  </Button>
                </>
              ) : (
                <FormControl size="small" sx={{ minWidth: 180, mr: 1 }}>
                  <InputLabel>Update Status</InputLabel>
                  <Select
                    value=""
                    onChange={(e) => handleBulkStatusUpdate(e.target.value)}
                    label="Update Status"
                    displayEmpty
                  >
                    <MenuItem value="" disabled>Update Status</MenuItem>
                    <MenuItem value="READ">Mark as Read</MenuItem>
                    <MenuItem value="RESPONDED">Mark as Responded</MenuItem>
                  </Select>
                </FormControl>
              )}

              <IconButton 
                size="small" 
                onClick={() => setSelected([])}
                sx={{ ml: 'auto' }}
              >
                <CloseIcon />
              </IconButton>
            </Box>
          </Box>
        )}

        {/* Data Table */}
        {viewMode === 'table' ? (
          <>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell padding="checkbox">
                      <Checkbox
                        indeterminate={
                          selected.length > 0 && selected.length < paginatedData.length
                        }
                        checked={
                          paginatedData.length > 0 && selected.length === paginatedData.length
                        }
                        onChange={handleSelectAll}
                      />
                    </TableCell>
                    {visibleColumns.name && <TableCell>Name</TableCell>}
                    {visibleColumns.email && <TableCell>Email</TableCell>}
                    {visibleColumns.phone && <TableCell>Phone</TableCell>}
                    {activeTab === 0 && visibleColumns.service && <TableCell>Service</TableCell>}
                    {activeTab === 1 && <TableCell>Subject</TableCell>}
                    {visibleColumns.date && (
                      <TableCell>{activeTab === 0 ? 'Appointment Date' : 'Received'}</TableCell>
                    )}
                    {visibleColumns.status && <TableCell>Status</TableCell>}
                    {visibleColumns.actions && <TableCell align="right">Actions</TableCell>}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {paginatedData.length > 0 ? (
                    paginatedData.map((row) => (
                      <TableRow
                        key={row.id}
                        hover
                        selected={selected.indexOf(row.id) !== -1}
                        onClick={() => {
                          const selectedIndex = selected.indexOf(row.id);
                          if (selectedIndex === -1) {
                            setSelected([...selected, row.id]);
                          } else {
                            setSelected(selected.filter(id => id !== row.id));
                          }
                        }}
                        sx={{ cursor: 'pointer' }}
                      >
                        <TableCell padding="checkbox" onClick={(e) => e.stopPropagation()}>
                          <Checkbox
                            checked={selected.indexOf(row.id) !== -1}
                            onChange={() => handleSelect(row.id)}
                            onClick={(e) => e.stopPropagation()}
                          />
                        </TableCell>

                        {visibleColumns.name && (
                          <TableCell>
                            <Box display="flex" alignItems="center">
                              {activeTab === 0 ? (
                                <>
                                  <PersonIcon fontSize="small" color="action" sx={{ mr: 1 }} />
                                  {`${row.firstName} ${row.lastName}`}
                                </>
                              ) : (
                                row.name
                              )}
                            </Box>
                          </TableCell>
                        )}

                        {visibleColumns.email && (
                          <TableCell>
                            <Box display="flex" alignItems="center">
                              <EmailIcon fontSize="small" color="action" sx={{ mr: 1 }} />
                              {row.email}
                            </Box>
                          </TableCell>
                        )}

                        {visibleColumns.phone && (
                          <TableCell>
                            <Box display="flex" alignItems="center">
                              <PhoneIcon fontSize="small" color="action" sx={{ mr: 1 }} />
                              {row.phone || 'N/A'}
                            </Box>
                          </TableCell>
                        )}

                        {activeTab === 0 && visibleColumns.service && (
                          <TableCell>{row.service}</TableCell>
                        )}

                        {activeTab === 1 && (
                          <TableCell>{row.subject}</TableCell>
                        )}

                        {visibleColumns.date && (
                          <TableCell>
                            <Box display="flex" alignItems="center">
                              {activeTab === 0 ? (
                                <>
                                  <CalendarIcon fontSize="small" color="action" sx={{ mr: 1 }} />
                                  {format(new Date(row.appointmentDate), 'MMM d, yyyy h:mm a')}
                                </>
                              ) : (
                                <>
                                  <TimeIcon fontSize="small" color="action" sx={{ mr: 1 }} />
                                  {format(new Date(row.createdAt), 'MMM d, yyyy')}
                                </>
                              )}
                            </Box>
                          </TableCell>
                        )}

                        {visibleColumns.status && (
                          <TableCell>
                            <FormControl fullWidth size="small">
                              <Select
                                value={row.status}
                                onChange={(e) => 
                                  handleStatusChange(row.id, e.target.value, activeTab === 0 ? 'appointment' : 'contact')
                                }
                                size="small"
                                sx={{ minWidth: 120 }}
                              >
                                {activeTab === 0 ? (
                                  <>
                                    <MenuItem value="PENDING">
                                      <StatusChip status="PENDING" />
                                    </MenuItem>
                                    <MenuItem value="CONFIRMED">
                                      <StatusChip status="CONFIRMED" />
                                    </MenuItem>
                                    <MenuItem value="COMPLETED">
                                      <StatusChip status="COMPLETED" />
                                    </MenuItem>
                                    <MenuItem value="CANCELLED">
                                      <StatusChip status="CANCELLED" />
                                    </MenuItem>
                                  </>
                                ) : (
                                  <>
                                    <MenuItem value="UNREAD">
                                      <StatusChip status="UNREAD" />
                                    </MenuItem>
                                    <MenuItem value="READ">
                                      <StatusChip status="READ" />
                                    </MenuItem>
                                    <MenuItem value="RESPONDED">
                                      <StatusChip status="RESPONDED" />
                                    </MenuItem>
                                  </>
                                )}
                              </Select>
                            </FormControl>
                          </TableCell>
                        )}

                        {visibleColumns.actions && (
                          <TableCell align="right">
                            <IconButton size="small">
                              <EditIcon fontSize="small" />
                            </IconButton>
                            <IconButton 
                              size="small"
                              onClick={(e) => {
                                e.stopPropagation();
                                // Handle delete
                              }}
                            >
                              <DeleteIcon fontSize="small" color="error" />
                            </IconButton>
                          </TableCell>
                        )}
                      </TableRow>
                    ))
                  ) : (
                    <TableRow>
                      <TableCell colSpan={10} align="center" sx={{ py: 3 }}>
                        <Box>
                          <Typography variant="subtitle1" color="textSecondary">
                            No {activeTab === 0 ? 'appointments' : 'messages'} found
                          </Typography>
                          <Button 
                            variant="outlined" 
                            color="primary" 
                            size="small" 
                            sx={{ mt: 1 }}
                            onClick={() => {
                              setSearchText('');
                              setFilters({
                                status: '',
                                dateRange: {
                                  start: subDays(new Date(), 30),
                                  end: new Date()
                                }
                              });
                            }}
                          >
                            Clear Filters
                          </Button>
                        </Box>
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>

            <Box display="flex" justifyContent="space-between" alignItems="center" mt={2}>
              <Typography variant="body2" color="textSecondary">
                Showing {filteredData.length === 0 ? 0 : (page * rowsPerPage) + 1} to{' '}
                {Math.min((page + 1) * rowsPerPage, filteredData.length)} of {filteredData.length} entries
              </Typography>

              <TablePagination
                rowsPerPageOptions={[5, 10, 25, 50]}
                component="div"
                count={filteredData.length}
                rowsPerPage={rowsPerPage}
                page={page}
                onPageChange={handleChangePage}
                onRowsPerPageChange={handleChangeRowsPerPage}
              />
            </Box>
          </>
        ) : (
          // Chart View Placeholder
          <Box sx={{ p: 4, textAlign: 'center' }}>
            <Typography variant="h6" color="textSecondary" gutterBottom>
              Analytics View
            </Typography>
            <Typography variant="body2" color="textSecondary">
              Charts and visualizations will be displayed here.
            </Typography>
            <Button 
              variant="outlined" 
              color="primary" 
              sx={{ mt: 2 }}
              onClick={() => setViewMode('table')}
            >
              Back to Table View
            </Button>
          </Box>
        )}
      </Paper>

      {/* Column Selector */}
      <Dialog 
        open={showColumnSelector} 
        onClose={() => setShowColumnSelector(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Visible Columns</DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="textSecondary" gutterBottom>
            Select which columns to display in the table:
          </Typography>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            {Object.entries(visibleColumns).map(([key, value]) => (
              <Grid item xs={6} sm={4} key={key}>
                <Box display="flex" alignItems="center">
                  <Checkbox
                    checked={value}
                    onChange={(e) => 
                      setVisibleColumns({...visibleColumns, [key]: e.target.checked})
                    }
                    size="small"
                  />
                  <Typography variant="body2">
                    {key.charAt(0).toUpperCase() + key.slice(1).replace(/([A-Z])/g, ' $1').trim()}
                  </Typography>
                </Box>
              </Grid>
            ))}
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setShowColumnSelector(false)}>Done</Button>
        </DialogActions>
      </Dialog>

      {/* Keyboard Shortcuts Dialog */}
      <Dialog 
        open={showShortcuts} 
        onClose={() => setShowShortcuts(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Keyboard Shortcuts</DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="textSecondary" gutterBottom>
            Use these keyboard shortcuts to navigate the dashboard more efficiently:
          </Typography>

          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle2" gutterBottom>Navigation</Typography>
            <Box component="ul" sx={{ pl: 2, '& li': { mb: 1 } }}>
              <li><kbd>R</kbd> - Refresh data</li>
              <li><kbd>F</kbd> - Toggle filters</li>
              <li><kbd>K</kbd> - Show/hide keyboard shortcuts</li>
              <li><kbd>ESC</kbd> - Close dialogs/modals</li>
            </Box>

            <Typography variant="subtitle2" gutterBottom sx={{ mt: 2 }}>Table Actions</Typography>
            <Box component="ul" sx={{ pl: 2, '& li': { mb: 1 } }}>
              <li><kbd>Space</kbd> - Select/deselect row</li>
              <li><kbd>Shift + Click</kbd> - Select multiple rows</li>
              <li><kbd>Ctrl + A</kbd> - Select all rows</li>
            </Box>
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setShowShortcuts(false)}>Close</Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={closeSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert 
          onClose={closeSnackbar} 
          severity={snackbar.severity} 
          variant="filled"
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default EnhancedDashboard;
